package com.warehouse.twin.controller;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.warehouse.twin.common.Result; import com.warehouse.twin.dto.EventReviewRequest; import com.warehouse.twin.entity.WarehouseEvent; import com.warehouse.twin.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/events") public class EventController {private final WarehouseEventService s;private final EventReviewService reviews;public EventController(WarehouseEventService s,EventReviewService r){this.s=s;reviews=r;}@GetMapping public Result<List<WarehouseEvent>> list(@RequestParam(required=false)String type){var q=Wrappers.<WarehouseEvent>lambdaQuery().eq(type!=null,WarehouseEvent::getEventType,type).orderByDesc(WarehouseEvent::getEventTime);return Result.ok(s.list(q));}@GetMapping("/{id}")public Result<WarehouseEvent> get(@PathVariable Long id){return Result.ok(s.getById(id));}@PostMapping("/{id}/review")public Result<WarehouseEvent> review(@PathVariable Long id,@Valid @RequestBody EventReviewRequest r){return Result.ok(reviews.review(id,r));}}
